  const low = s => String(s || "").toLowerCase().replace(/ё/g, "е");
  function find(subject, topic) {
    const key = subject === "ru1" ? "ru" : subject === "lit1" ? "lit" : subject;
    const t = low(topic);
    const list = key === "ru" ? RU : (OTHER[key] || []);
    const hit = list.find(x => !x.late && x.re.test(t)) || list.find(x => x.late && x.re.test(t));
    return hit || null;
  }
  /* Markdown-блок схемы для памятки и конспекта */
  function md(sc, { head = "## Схема", example = true } = {}) {
    if (!sc) return "";
    let out = `${head}${sc.t ? `: ${sc.t}` : ""}\n\n`;
    out += sc.s.map(x => `- ${html(x)}`).join("\n") + "\n\n";
    if (example && sc.ex?.length) out += `**Пример:** ${sc.ex.map(html).join(" ")}\n\n`;
    if (sc.l) out += `*${html(sc.l)}*\n\n`;
    return out;
  }
  /* Плоский Markdown-блок схемы без HTML: для слайдов, Word, PowerPoint и карточек Deck */
  function plainMd(sc, { head = "", example = true } = {}) {
    if (!sc) return "";
    let out = head ? `${head}${sc.t ? `: ${sc.t}` : ""}\n\n` : "";
    out += (sc.s || []).map(x => `- ${plain(x)}`).join("\n");
    if (example && sc.ex?.length) out += `\n\n**Примеры:** ${sc.ex.map(plain).join(" · ")}`;
    if (sc.l) out += `\n\n*${plain(sc.l)}*`;
    return out;
  }
  /* вставить схему в памятку: сразу после строки «Тема:» первой части (если схемы ещё нет) */
  function inject(text, subject, topic, sc) {
    const src = String(text || ""); if (/^## Схема/m.test(src)) return src;
    const S = sc || find(subject, topic); if (!S) return src;
    const block = md(S);
    const m = src.match(/^# (Памятка|Лист для запоминания)[^\n]*\n+(\*\*Тема:\*\*[^\n]*\n+)?/m);
    if (!m) return src;
    const at = m.index + m[0].length;
    return src.slice(0, at) + block + src.slice(at);
  }
  return { RU, OTHER, find, md, plainMd, html, plain, inject, LEG_SYNT, LEG_MORF };
